const sample=[
 ['VM-101','Base plate','Pump skid',2,'316L steel','8 mm plate','A','Drawing 01 · p1'],
 ['VM-102','Triangular gusset','Pump skid',4,'316L steel','6 mm plate','A','Drawing 01 · p1'],
 ['VM-103','Motor bracket','Pump skid',null,'Mild steel','12 mm plate','A','Drawing 02 · p2'],
 ['VM-201','Cable tray support','Cable tray',6,'5083 aluminium','5 mm plate','B','Drawing 03 · p3'],
 ['VM-202','Pipe clamp','Cable tray',8,'316L steel','25 mm bar','B','Drawing 03 · p3'],
 ['VM-203','Drain cover','Drain assembly',1,'5083 aluminium','4 mm plate','','Drawing 04 · p4']
];
let rows=sample.map(r=>r.slice()),sheet='Master BOM',selected=null,view=[];const grid=document.querySelector('#grid'),entry=document.querySelector('#cell-value'),address=document.querySelector('#address'),apply=document.querySelector('#apply'),guidance=document.querySelector('#guidance');
const state=r=>(r[3]===null||r[6]==='')?'Review':'Ready';
const headers={ 'Master BOM':['Part no.','Description','Assembly','Quantity','Material','Stock','Revision','Source','Status'], 'Review queue':['Part no.','Assembly','Source','Field','Issue','Action'], 'Source pages':['Drawing','Assembly','Part rows','Needs review']};
function buildView(){if(sheet==='Master BOM')return rows.map((r,i)=>({values:[...r,state(r)],source:i,row:i+2})).filter(r=>!document.querySelector('#review-only').checked||state(rows[r.source])==='Review');if(sheet==='Review queue'){return rows.flatMap((r,i)=>{const a=[];if(r[3]===null)a.push({values:[r[0],r[2],r[7],'Quantity','Unreadable cell','Edit quantity in Master BOM'],source:i,row:i+2});if(r[6]==='')a.push({values:[r[0],r[2],r[7],'Revision','Revision missing','Edit revision in Master BOM'],source:i,row:i+2});return a})}return [...new Set(rows.map(r=>r[7]))].map((page,i)=>{const parts=rows.filter(r=>r[7]===page);return {values:[page,parts[0][2],parts.length,parts.filter(r=>state(r)==='Review').length],source:null,row:i+2}})}
function selectCell(v,c,focus=false){selected={v,c};const rec=view[v],value=rec.values[c];address.textContent=String.fromCharCode(65+c)+rec.row;const editable=sheet==='Master BOM'&&(c===3||c===6);entry.readOnly=!editable;apply.disabled=!editable;entry.value=sheet==='Master BOM'&&c===8?`=IF(OR(D${rec.row}="",G${rec.row}=""),"Review","Ready")`:(value??'');guidance.textContent=editable?(c===3?'Enter a whole quantity, then press Enter or ✓.':'Enter the drawing revision, then press Enter or ✓.'):(sheet==='Review queue'?'Open Master BOM to correct the flagged field.':'Select a quantity or revision cell to edit it.');grid.querySelectorAll('td.selected').forEach(td=>{td.classList.remove('selected');td.setAttribute('aria-selected','false')});const cell=grid.querySelector(`[data-v="${v}"][data-c="${c}"]`);if(cell){cell.classList.add('selected');cell.setAttribute('aria-selected','true');if(focus)cell.focus()}}
function render(){view=buildView();grid.replaceChildren();const head=document.createElement('thead'),letters=document.createElement('tr');for(let c=-1;c<headers[sheet].length;c++){const th=document.createElement('th');th.textContent=c<0?'':String.fromCharCode(65+c);if(c<0)th.className='row-number';letters.append(th)}head.append(letters);grid.append(head);const body=document.createElement('tbody'),label=document.createElement('tr');label.className='field-headers';const rn=document.createElement('th');rn.className='row-number';rn.textContent='1';label.append(rn);headers[sheet].forEach(h=>{const td=document.createElement('td');td.textContent=h;label.append(td)});body.append(label);view.forEach((r,v)=>{const tr=document.createElement('tr');if(sheet==='Master BOM'&&state(rows[r.source])==='Review')tr.className='row-review';const rowNum=document.createElement('th');rowNum.className='row-number';rowNum.textContent=r.row;tr.append(rowNum);r.values.forEach((value,c)=>{const td=document.createElement('td');td.textContent=value??'';td.dataset.v=v;td.dataset.c=c;td.setAttribute('role','gridcell');td.tabIndex=0;td.setAttribute('aria-selected','false');if(sheet==='Master BOM'){if(c===3||c===6)td.classList.add('editable');if((c===3&&value===null)||(c===6&&value===''))td.classList.add('empty-cell');if(c===8)td.classList.add(value==='Review'?'status-review':'status-ready')}td.onclick=()=>selectCell(v,c);td.onkeydown=e=>{const moves={ArrowDown:[1,0],ArrowUp:[-1,0],ArrowRight:[0,1],ArrowLeft:[0,-1]};if(moves[e.key]){e.preventDefault();const[dv,dc]=moves[e.key];selectCell(Math.max(0,Math.min(view.length-1,v+dv)),Math.max(0,Math.min(r.values.length-1,c+dc)),true)}else if(e.key==='Enter'){e.preventDefault();selectCell(v,c);if(!entry.readOnly)entry.focus()}};tr.append(td)});body.append(tr)});if(!view.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=headers[sheet].length+1;td.textContent='No rows need review.';td.style.padding='28px';tr.append(td);body.append(tr)}grid.append(body);const count=rows.filter(r=>state(r)==='Ready').length;document.querySelector('#count').textContent=`${count} / ${rows.length} rows ready`;document.querySelector('#review-only').disabled=sheet!=='Master BOM';if(view.length)selectCell(0,0);else{selected=null;address.textContent='—';entry.value='';entry.readOnly=true;apply.disabled=true;guidance.textContent='The sample review queue is clear.'}}
function save(){if(!selected||sheet!=='Master BOM')return;const rec=view[selected.v],c=selected.c;if(c!==3&&c!==6)return;const text=entry.value.trim();if(c===3&&text!==''&&(!Number.isInteger(Number(text))||Number(text)<1)){guidance.textContent='Use a positive whole number, or leave the quantity blank for review.';return}const source=rec.source;rows[source][c]=c===3?(text===''?null:Number(text)):text;render();const n=view.findIndex(r=>r.source===source);if(n>=0)selectCell(n,c);guidance.textContent=`${rows[source][0]} updated in this example. ${state(rows[source])==='Ready'?'Its review warning is clear.':'Another field still needs review.'}`}
apply.onclick=save;entry.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();save()}};document.querySelector('#review-only').onchange=render;document.querySelector('#reset').onclick=()=>{rows=sample.map(r=>r.slice());document.querySelector('#review-only').checked=false;render()};document.querySelectorAll('[data-sheet]').forEach(b=>b.onclick=()=>{sheet=b.dataset.sheet;document.querySelectorAll('[data-sheet]').forEach(t=>t.setAttribute('aria-selected',String(t===b)));render()});render();
